938	  /**
939	   * Fastify still accepts the router options ("ignoreTrailingSlash",
940	   * "caseSensitive", ...) at the top level, but "initialConfig.routerOptions"
941	   * only reflects them when they are passed through "routerOptions". As the
942	   * adapter always passes "routerOptions" (for the version constraint), the
943	   * top-level values are folded in so that plugins relying on
944	   * "initialConfig.routerOptions" (like @fastify/middie) normalize request
945	   * paths exactly like the router does.
946	   */
947	  private getTopLevelRouterOptions(
948	    options?: FastifyServerOptions,
949	  ): NonNullable<FastifyServerOptions['routerOptions']> {
950	    const routerOptions: Record<string, unknown> = {};
951	    const routerOptionKeys = [
952	      'ignoreTrailingSlash',
953	      'ignoreDuplicateSlashes',
954	      'caseSensitive',
955	      'useSemicolonDelimiter',
956	      'maxParamLength',
957	      'allowUnsafeRegex',
958	    ] as const;
959	    for (const key of routerOptionKeys) {
960	      if (options?.[key] !== undefined) {
961	        routerOptions[key] = options[key];
962	      }
963	    }
964	    return routerOptions;
965	  }
