/**
 * Installs a request gate directly on the underlying HTTP server, ahead of
 * Fastify's own request handler. Once the application starts closing
 * (`beforeClose()`), every new request - including requests pipelined on a
 * keep-alive connection - is rejected with `503 Service Unavailable` and
 * `Connection: close` before it can reach any route, guard, pipe or
 * interceptor, while requests already admitted complete normally.
 */
private install503OnClosingGate() {
  if (this.is503OnClosingGateInstalled) {
    return;
  }
  this.is503OnClosingGateInstalled = true;

  const server = this.instance.server as unknown as http.Server;
  const requestListeners = server.listeners('request');
  server.removeAllListeners('request');
  server.on('request', (req, res) => {
    if (!this.isShuttingDown) {
      for (const listener of requestListeners) {
        listener.call(server, req, res);
      }
      return;
    }
    // "Connection: close" is not a valid HTTP/2 header (mirrors Fastify's
    // own closing behavior)
    if (req.httpVersionMajor !== 2) {
      res.setHeader('Connection', 'close');
    }
    res.writeHead(503, {
      'Content-Type': 'text/plain; charset=utf-8',
      'Content-Length': '19',
    });
    res.end('Service Unavailable');
  });
}
```

